-- ============================================
-- LUMA — Thème 6 : LONG 2/3 x4 — Organiser une fête et gérer les conséquences
-- ============================================


update scenarios set content = '{"characters": {"roommate": "ton/ta coloc", "neighbor": "le voisin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "roommate", "text": "So, are we really doing this party Saturday? We should plan it properly.", "text_fr": "Alors, on fait vraiment cette fête samedi ? On devrait bien la planifier.", "choices": [{"text": "Yes! Let''s make a guest list and figure out food and drinks.", "text_fr": "Oui ! Faisons une liste d''invités et voyons pour la nourriture et les boissons.", "next": "n2"}, {"text": "Definitely — should we tell the neighbors in advance, just in case?", "text_fr": "Carrément — on devrait prévenir les voisins à l''avance, au cas où ?", "next": "n2b"}]}, "n2": {"speaker": "roommate", "text": "Good idea. I''ll handle drinks if you handle snacks?", "text_fr": "Bonne idée. Je m''occupe des boissons si tu t''occupes des snacks ?", "choices": [{"text": "Deal, I''ll grab stuff tomorrow after work.", "text_fr": "Marché conclu, je vais chercher ça demain après le travail.", "next": "n3"}]}, "n2b": {"speaker": "roommate", "text": "Good thinking, that could save us some awkwardness later.", "text_fr": "Bonne pensée, ça pourrait nous éviter des gênes plus tard.", "choices": [{"text": "I''ll knock on their door this afternoon to give them a heads up.", "text_fr": "Je vais frapper à leur porte cet après-midi pour les prévenir.", "next": "n3"}]}, "n3": {"speaker": "roommate", "text": "Perfect. How many people do you think we should invite?", "text_fr": "Parfait. Combien de personnes tu penses qu''on devrait inviter ?", "choices": [{"text": "Maybe keep it around 15-20, so it doesn''t get out of hand.", "text_fr": "Peut-être rester autour de 15-20, pour que ça déborde pas.", "next": "n4"}, {"text": "Let''s go bigger, like 30 people, more the merrier!", "text_fr": "Allons plus grand, genre 30 personnes, plus on est de fous plus on rit !", "next": "n4b"}]}, "n4": {"speaker": "roommate", "text": "That sounds manageable, I like that.", "text_fr": "Ça semble gérable, j''aime bien.", "choices": [{"text": "Agreed, let''s finalize the list tonight.", "text_fr": "D''accord, finalisons la liste ce soir.", "next": "n5"}]}, "n4b": {"speaker": "roommate", "text": "Hmm, that might get a bit chaotic for our apartment size, but let''s try.", "text_fr": "Hmm, ça pourrait devenir un peu chaotique pour la taille de notre appart, mais essayons.", "choices": [{"text": "You''re probably right, let''s scale it down a bit to be safe.", "text_fr": "T''as probablement raison, réduisons un peu par sécurité.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(Saturday night arrives — the party is in full swing, music playing, everyone having fun.)", "text_fr": "(Samedi soir arrive — la fête bat son plein, musique qui joue, tout le monde s''amuse.)", "choices": [{"text": "(Enjoy the party, keeping an eye on the time.)", "text_fr": "(Profite de la fête, en gardant un œil sur l''heure.)", "next": "n6"}]}, "n6": {"speaker": "neighbor", "text": "(Knocks firmly) Excuse me, it''s getting pretty late and the music is really loud.", "text_fr": "(Frappe fermement) Excusez-moi, il commence à se faire tard et la musique est vraiment forte.", "choices": [{"text": "I''m so sorry, we''ll turn it down right away.", "text_fr": "Je suis vraiment désolé, on baisse tout de suite.", "next": "n7"}, {"text": "You''re right, I completely lost track of time. My apologies.", "text_fr": "Vous avez raison, j''ai complètement perdu la notion du temps. Mes excuses.", "next": "n7"}]}, "n7": {"speaker": "roommate", "text": "(Turns down the music immediately) Sorry everyone, let''s keep it down a bit from here.", "text_fr": "(Baisse la musique immédiatement) Désolé tout le monde, restons plus calmes à partir de maintenant.", "choices": [{"text": "Good call, better to keep things friendly with the neighbors.", "text_fr": "Bonne décision, mieux vaut rester en bons termes avec les voisins.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(The party winds down peacefully, and guests start leaving around midnight.)", "text_fr": "(La fête se termine paisiblement, et les invités commencent à partir vers minuit.)", "choices": [{"text": "(Say goodbye to the last guests and survey the mess.)", "text_fr": "(Dis au revoir aux derniers invités et évalue le désordre.)", "next": "n9"}]}, "n9": {"speaker": "roommate", "text": "(Looking at the messy living room) Well... that''s a lot to clean up tomorrow.", "text_fr": "(Regardant le salon en désordre) Bon... y''a beaucoup à nettoyer demain.", "choices": [{"text": "Let''s just tackle it together first thing in the morning.", "text_fr": "Attaquons-nous à ça ensemble dès demain matin.", "next": "n10"}, {"text": "How about we split it — I do the kitchen, you do the living room?", "text_fr": "Et si on partageait — je fais la cuisine, tu fais le salon ?", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(The next morning, you both clean up together, a bit tired but laughing about the night.)", "text_fr": "(Le lendemain matin, vous nettoyez ensemble tous les deux, un peu fatigués mais en riant de la soirée.)", "choices": [{"text": "Despite the neighbor thing, that was a really fun night.", "text_fr": "Malgré l''histoire avec le voisin, c''était vraiment une soirée fun.", "next": "n11"}, {"text": "We should apologize to the neighbor properly today, just to be safe.", "text_fr": "On devrait s''excuser correctement auprès du voisin aujourd''hui, par sécurité.", "next": "n11b"}]}, "n11": {"speaker": "roommate", "text": "It really was! We should do this again sometime, just maybe end it a bit earlier.", "text_fr": "C''était vraiment ça ! On devrait refaire ça un jour, juste peut-être finir un peu plus tôt.", "choices": [{"text": "Agreed, lesson learned for next time.", "text_fr": "D''accord, leçon retenue pour la prochaine fois.", "next": "end_fun"}]}, "n11b": {"speaker": "roommate", "text": "Good idea, maybe bring them some cookies as a peace offering too.", "text_fr": "Bonne idée, on pourrait leur apporter des cookies en guise de paix aussi.", "choices": [{"text": "Perfect idea, let''s do that this afternoon.", "text_fr": "Excellente idée, faisons ça cet après-midi.", "next": "end_thoughtful"}]}, "end_fun": {"speaker": "roommate", "text": "Definitely! Great party, minor hiccup, but overall a success.", "text_fr": "Carrément ! Super fête, petit accroc, mais un succès dans l''ensemble.", "end": true, "ending_label": "Fête réussie malgré un petit accroc 🎉🏠"}, "end_thoughtful": {"speaker": "neighbor", "text": "(Later, accepting the cookies) That''s really thoughtful, thank you — no hard feelings.", "text_fr": "(Plus tard, acceptant les cookies) C''est vraiment gentil, merci — pas de rancune.", "end": true, "ending_label": "Relations de voisinage réparées avec attention 🍪😊"}}}'::jsonb, is_playable = true
where title = 'Organiser une fête et gérer les conséquences'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
